// Offline support: registers the service worker (sw.js, generated by scripts/build-sw.mjs),
// offers a reload when a new version is ready, and can download all generated audio of the chosen
// voice into the audio cache so lessons and stories work without a connection.

import { t } from './i18n.js';
import { toast } from './ui/toast.js';
import { ttsManifest, ttsVoice } from './audio.js';

const AUDIO_CACHE = 'tolva-audio-v1';
const supported = 'serviceWorker' in navigator && 'caches' in window && location.protocol !== 'file:';

function offerUpdate(worker) {
  toast(t('offline.update'), {
    action: {
      label: t('offline.reload'),
      run: () => worker.postMessage({ type: 'skipWaiting' }),
    },
  });
}

let registration = Promise.resolve(null);

export function registerWorker() {
  registration = register();
  return registration;
}

async function register() {
  if (!supported) return null;
  try {
    const hadController = Boolean(navigator.serviceWorker.controller);
    const reg = await navigator.serviceWorker.register(new URL('../sw.js', import.meta.url));
    if (reg.waiting && hadController) offerUpdate(reg.waiting);
    reg.addEventListener('updatefound', () => {
      const worker = reg.installing;
      worker?.addEventListener('statechange', () => {
        if (worker.state === 'installed' && navigator.serviceWorker.controller) offerUpdate(worker);
      });
    });
    let reloading = false;
    navigator.serviceWorker.addEventListener('controllerchange', () => {
      if (!hadController || reloading) return;
      reloading = true;
      location.reload();
    });
    return reg;
  } catch (e) {
    console.warn('Service worker not registered.', e);
    return null;
  }
}

/** 'unsupported' (also when registration failed) | 'installing' | 'ready' */
export async function offlineState() {
  const reg = await registration;
  if (!reg) return 'unsupported';
  return reg.active ? 'ready' : 'installing';
}

function audioFiles(manifest) {
  return [...new Set(Object.values(manifest.texts).map((e) => new URL(`../data/audio/${e.f}`, import.meta.url).href))];
}

/** How many generated audio files are already cached, of how many. */
export async function audioCacheStatus() {
  if (!supported) return null;
  const manifest = await ttsManifest();
  const urls = audioFiles(manifest);
  const cache = await caches.open(AUDIO_CACHE);
  const have = new Set((await cache.keys()).map((r) => r.url));
  return { manifest, urls, cached: urls.filter((u) => have.has(u)).length, total: urls.length };
}

/** Removes cached generated audio of the voices not in use (after the learner changes voice). */
export async function dropOtherVoices() {
  if (!supported) return 0;
  const cache = await caches.open(AUDIO_CACHE);
  const mine = `/data/audio/tts/${ttsVoice()}/`;
  const others = (await cache.keys()).filter((r) => /\/data\/audio\/tts\//.test(r.url) && !new URL(r.url).pathname.includes(mine));
  await Promise.all(others.map((r) => cache.delete(r)));
  return others.length;
}

/** Downloads every generated audio file of the chosen voice not yet cached. onProgress(done, total). */
export async function cacheAllAudio(onProgress) {
  await dropOtherVoices();
  const { urls } = await audioCacheStatus();
  const cache = await caches.open(AUDIO_CACHE);
  const have = new Set((await cache.keys()).map((r) => r.url));
  const todo = urls.filter((u) => !have.has(u));
  let done = urls.length - todo.length;
  onProgress?.(done, urls.length);
  const BATCH = 12;
  for (let i = 0; i < todo.length; i += BATCH) {
    await Promise.all(
      todo.slice(i, i + BATCH).map(async (u) => {
        const res = await fetch(u);
        if (res.ok) await cache.put(u, res);
        done++;
      }),
    );
    onProgress?.(done, urls.length);
  }
  return done;
}
